       <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/raceid> ?raceid ;
       <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/driverid> ?driverid ;
       <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/statusid> ?statusid .
  FILTER(xsd:long(?raceid) = 872)
  ?status a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Status> ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Status/statusid> ?statusid ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Status/status> "Finished" .
  ?driver a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver> ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/driverid> ?driverid ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/forename> ?forename ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/surname> ?surname ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/dob> ?dob .
