SELECT ?name WHERE {
  {
    SELECT (MIN(?y) AS ?minYear) WHERE {
      ?r a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race> ;
         <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/year> ?y .
    }
  }
  {
    SELECT (MIN(?mon) AS ?minMonth) WHERE {
      {
        SELECT (MIN(?y3) AS ?minYear3) WHERE {
          ?r3 a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race> ;
              <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/year> ?y3 .
        }
      }
      ?r2 a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race> ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/year> ?y2 ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/date> ?d2 .
      FILTER(xsd:integer(?y2) = ?minYear3)
      BIND(SUBSTR(STR(?d2),6,2) AS ?mon)
    }
  }
  ?race a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race> ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/year> ?year ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/date> ?date ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/name> ?name .
  FILTER(xsd:integer(?year) = ?minYear)
  BIND(SUBSTR(STR(?date),6,2) AS ?month)
  FILTER(?month = ?minMonth)
}

