  ?r853 a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result> ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/raceid> 853 ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/driverid> ?driverid ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/fastestlapspeed> ?speed853 .

