SELECT ?forename ?surname ?totalPoints WHERE {
  {
    SELECT ?driverid (SUM(?points) AS ?totalPoints) WHERE {
      ?result a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result> ;
              <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/driverid> ?driverid ;
              <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Result/points> ?points .
    }
    GROUP BY ?driverid
    ORDER BY DESC(?totalPoints)
    LIMIT 1
  }
  ?driver a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver> ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/driverid> ?driverid ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/forename> ?forename ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/surname> ?surname .
}

