      <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime/driverid> ?did ;
      <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime/milliseconds> ?ms .
  ?d a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/driverid> ?did ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/forename> ?fn ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/surname> ?sn .
  BIND(CONCAT(?fn, " ", ?sn) AS ?fullName)
}
ORDER BY xsd:decimal(?ms)
LIMIT 20

SELECT (xsd:decimal(?matchCount) / xsd:decimal(?totalCount) * 100 AS ?percentage)
WHERE {
  {
    SELECT (COUNT(*) AS ?totalCount) WHERE {
      ?lt a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime> ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime/raceid> ?raceid .
      ?race a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race> ;
            <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/raceid> ?raceid ;
            <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/year> ?year .
      FILTER(xsd:integer(?year) >= 2000 && xsd:integer(?year) <= 2005)
    }
  }
  {
    SELECT (COUNT(*) AS ?matchCount) WHERE {
      ?lt2 a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime> ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime/raceid> ?raceid2 ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime/driverid> ?driverid2 ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/LapTime/lap> ?lap2 .
      ?race2 a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race> ;
            <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/raceid> ?raceid2 ;
            <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/year> ?year2 .
      ?driver2 a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver> ;
              <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/driverid> ?driverid2 ;
              <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/dob> ?dob2 .
      FILTER(xsd:integer(?year2) >= 2000 && xsd:integer(?year2) <= 2005)
      FILTER(xsd:integer(?lap2) > 50)
      FILTER(?dob2 < "1985-01-01")
    }
  }
}

SELECT ?year ?name ?date ?time WHERE {
  {
    SELECT (MAX(?dob) AS ?maxdob) WHERE {
      ?d a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver> ;
         <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/dob> ?dob ;
         <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/driverid> ?did .
      ?q a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Qualifying> ;
         <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Qualifying/driverid> ?did .
    }
