  ?driver a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver> ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/dob> ?maxdob ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/driverid> ?driverid .
  ?qual a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Qualifying> ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Qualifying/driverid> ?driverid ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Qualifying/raceid> ?raceid .
  ?race a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race> ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/raceid> ?raceid ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/year> ?year ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/name> ?name ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/date> ?date ;
        <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/time> ?time .
