     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/circuitid> ?circuitid ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/year> "2008"^^<http://www.w3.org/2001/XMLSchema#long> ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/round> "3"^^<http://www.w3.org/2001/XMLSchema#long> ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/raceid> ?raceid .
  ?q a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Qualifying> ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Qualifying/raceid> ?raceid ;
     <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Qualifying/position> "1"^^<http://www.w3.org/2001/XMLSchema#long> ;
