SELECT ?fullName ?nationality ?raceName
WHERE {
  {
    SELECT ?driver WHERE {
      ?driver a <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver> ;
               <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/dob> ?dob .
    }
    ORDER BY DESC(?dob)
    LIMIT 1
  }
  ?driver <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/forename> ?forename ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/surname> ?surname ;
          <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Driver/nationality> ?nationality .
  BIND(CONCAT(?forename, " ", ?surname) AS ?fullName)

  {
    SELECT ?driver (MIN(?date) AS ?minDate) WHERE {
      ?result <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Results/hasDrivers> ?driver ;
              <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Results/hasRaces> ?race .
      ?race <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/date> ?date .
    }
    GROUP BY ?driver
  }

  ?result2 <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Results/hasDrivers> ?driver ;
           <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Results/hasRaces> ?race2 .
  ?race2 <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/date> ?minDate ;
         <http://bird-bird_formula_1-ontology-20261002-181806/ontology/vkg-bird_formula_1/Race/name> ?raceName .
}
